{"file_path":"src/parse.js","content":"/**
 * Parsing and validation of an election description.
 *
 * A parse failure is reported by throwing a ParseError whose message is the
 * exact line that belongs on standard error (without its newline).
 */

export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function fail(message) {
  throw new ParseError(message)
}

/**
 * Split the raw input into logical lines, dropping the empty tail that a
 * trailing newline leaves behind. Line numbers are the 1-based index here.
 */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parse an election, returning { candidates, ballots } where a ballot is
 * { count, names } with names ordered from most to least preferred.
 */
export function parseElection(input) {
  const lines = splitLines(input)
  let candidates = null
  const ballots = []

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i].trim()
    const n = i + 1
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`line ${n}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 2) fail(`line ${n}: expected candidates <name>...`)
      const declared = []
      const seen = new Set()
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) fail(`line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
        declared.push(name)
      }
      candidates = declared
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${n}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 3) fail(`line ${n}: expected ballot <count> <candidate>...`)
      const count = words[1]
      if (!COUNT.test(count)) fail(`line ${n}: count must be a positive integer`)
      const names = []
      const seen = new Set()
      for (const name of words.slice(2)) {
        if (!candidates.includes(name)) fail(`line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${n}: candidate ${name} is repeated`)
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count: Number(count), names })
    } else {
      fail(`line ${n}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
"}

