{"file_path":"src/count.js","content":"/** The instant-runoff count itself. */

/**
 * Run the election. Returns { rounds, winner } where rounds is a list of
 * { counts, exhausted, eliminated } and counts is a Map from the name of a
 * candidate still continuing in that round to the votes it received.
 * winner is null when no candidate ever reached a majority.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    let active = 0
    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
        active += ballot.count
      }
    }
    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)

    if (active === 0) return { rounds, winner: null }

    let winner = null
    for (const [name, votes] of counts) {
      if (votes * 2 > active) winner = name
    }
    if (winner !== null) return { rounds, winner }

    const loser = pickLoser(counts, rounds)
    round.eliminated = loser
    continuing.delete(loser)
  }
}

/** Choose the candidate to eliminate among those tied for fewest votes. */
function pickLoser(counts, rounds) {
  let tied = [...counts.keys()]
  const fewest = Math.min(...tied.map((name) => counts.get(name)))
  tied = tied.filter((name) => counts.get(name) === fewest)

  for (let r = 0; r < rounds.length && tied.length > 1; r += 1) {
    const at = (name) => rounds[r].counts.get(name)
    const least = Math.min(...tied.map(at))
    tied = tied.filter((name) => at(name) === least)
  }

  let loser = tied[0]
  for (const name of tied) {
    if (name > loser) loser = name
  }
  return loser
}
"}

