{"file_path":"src/format.js","content":"/** Rendering of a finished count. */

function byVotesThenName(counts) {
  return [...counts.keys()].sort((a, b) => {
    const diff = counts.get(b) - counts.get(a)
    if (diff !== 0) return diff
    return a < b ? -1 : a > b ? 1 : 0
  })
}

export function formatRounds(result) {
  const out = []
  result.rounds.forEach((round, index) => {
    const parts = byVotesThenName(round.counts).map((name) => `${name}=${round.counts.get(name)}`)
    parts.push(`exhausted=${round.exhausted}`)
    out.push(`round ${index + 1}: ${parts.join(' ')}`)
    if (round.eliminated !== null) out.push(`eliminated ${round.eliminated}`)
  })
  out.push(outcome(result))
  return out.map((line) => `${line}\n`).join('')
}

export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${outcome(result)}\n`
}

function outcome(result) {
  return result.winner === null ? 'no winner' : `winner ${result.winner}`
}
"}

